class Solution { public int[] minimaxPathQueries(int n,int[][]e,int[][]q){int inf=1000000000;int[][]d=new int[n][n];for(int i=0;i<n;i++){Arrays.fill(d[i],inf);d[i][i]=0;}for(int[]x:e){d[x[0]][x[1]]=Math.min(d[x[0]][x[1]],x[2]);d[x[1]][x[0]]=Math.min(d[x[1]][x[0]],x[2]);}for(int k=0;k<n;k++)for(int i=0;i<n;i++)for(int j=0;j<n;j++)d[i][j]=Math.min(d[i][j],Math.max(d[i][k],d[k][j]));int[]a=new int[q.length];for(int i=0;i<q.length;i++)a[i]=d[q[i][0]][q[i][1]]==inf?-1:d[q[i][0]][q[i][1]];return a;} }
